/**
 * ALPHA SCOUT — seed data.
 *
 * The 467 deals below are copied from the Alpha Scout listings board
 * (daily feed sync, 2026-11-19T08:54:57.947Z): same ids, titles, tracks, estimated values,
 * valueUsd, eligibility, costType, expiry dates, source URLs, requirements,
 * action steps, verification status and risk notes. Values, dates and links
 * are unchanged; listing notes are written for a general audience.
 *
 * Expiry handling is date-relative: a deal whose expiresOn is in the past
 * is treated as expired (it leaves the active list; only saved deals stay
 * visible in the Archive tab); one expiring within 48 hours is
 * flagged Expiring Soon. "Ongoing" = expiresOn is null.
 */

export type Track =
  | "scholarships"
  | "jobs"
  | "internships"
  | "ai-tools"
  | "crypto"
  | "nfts"
  | "banking"
  | "cloud"
  | "software";

export type CostType = "truly-free" | "free-tier" | "free-trial-card";
export type Verification = "verified" | "pending";

export interface Deal {
  id: number;
  title: string;
  track: Track;
  estimatedValue: string;
  valueUsd: number | null;
  eligibility: string;
  costType: CostType;
  /** YYYY-MM-DD, or null = Ongoing. */
  expiresOn: string | null;
  sourceUrl: string;
  requirements: string;
  /** Numbered steps, e.g. "1. Do X. 2. Do Y." */
  actionSteps: string;
  verification: Verification;
  riskNote: string;
  status: "active" | "archived";
}

